/*
 * A003146  Positions of letter c in the tribonacci word abacabaabacababac...
 *          generated by a->ab, b->ac, c->a (cf. A092782).
 * https://oeis.org/A003146
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Tribonacci word S_n = S_{n-1} S_{n-2} S_{n-3} with S_1="a",
 *            S_2="ab", S_3="abac"; find n-th 'c' position
 * Range:     u8 n <= 2, u16 n <= 2, u32 n <= 2, u64 n <= 9880, u128 n <= 9880,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

static struct {
    seq_t len, cnt;
} seg[100];

static void init_seg(void) {
    seg[0].len = 1; seg[0].cnt = 0;  // S_1 = "a"
    seg[1].len = 2; seg[1].cnt = 0;  // S_2 = "ab"
    seg[2].len = 4; seg[2].cnt = 1;  // S_3 = "abac"
    
    for (int i = 3; i < 100; i++) {
        seg[i].len = seg[i-1].len + seg[i-2].len + seg[i-3].len;
        seg[i].cnt = seg[i-1].cnt + seg[i-2].cnt + seg[i-3].cnt;
        if (seg[i].len > ((seq_t)1 << 62)) break;
    }
}

static seq_t find_nth(int si, seq_t n) {
    if (si <= 1) return 0;  // No 'c' in S_1 or S_2
    if (si == 2) return 4;  // S_3 = "abac", single 'c' at position 4
    
    // si >= 3: recurse using S_si = S_{si-1} + S_{si-2} + S_{si-3}
    seq_t c1 = seg[si-1].cnt;
    seq_t c2 = seg[si-2].cnt;
    
    if (n <= c1) {
        return find_nth(si-1, n);
    } else if (n <= c1 + c2) {
        return seg[si-1].len + find_nth(si-2, n - c1);
    } else {
        return seg[si-1].len + seg[si-2].len + find_nth(si-3, n - c1 - c2);
    }
}

seq_t a(idx_t n) {
    static bool initialized = false;
    if (!initialized) {
        init_seg();
        initialized = true;
    }
    
    int si = 2;
    seq_t nn = (seq_t)n;
    while (si < 100 && seg[si].cnt < nn) {
        si++;
    }
    
    return find_nth(si, nn);
}
